import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const API_BASE = "http://localhost:8000/api";

const IMPACT_METRICS = [
  { value: "45K+", label: "Pets Reunited", icon: "home" },
  { value: "98%", label: "Success Rate", icon: "check_circle" },
  { value: "8K+", label: "Adoptions Facilitated", icon: "volunteer_activism" },
];

function HomePage() {
  const [feedbacks, setFeedbacks] = useState([]);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: "",
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    fetchFeedbacks();
  }, []);

  const fetchFeedbacks = async () => {
    try {
      const response = await fetch(`${API_BASE}/feedbacks/`);
      if (response.ok) {
        const data = await response.json();
        setFeedbacks(data);
      }
    } catch (err) {
      console.error("Error fetching feedbacks:", err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    setSuccess("");

    try {
      const response = await fetch(`${API_BASE}/feedbacks/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        setSuccess("Thank you for your feedback!");
        setFormData({ name: "", email: "", message: "" });
        fetchFeedbacks();
      } else {
        const errorData = await response.json();
        setError(errorData.detail || "Failed to submit feedback");
      }
    } catch (err) {
      setError("An error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-teal-50 to-green-50">
      <section className="relative bg-gradient-to-r from-blue-900 to-teal-600 text-white py-24 px-6 overflow-hidden">
        <div className="absolute inset-0 bg-black opacity-20"></div>
        <div className="relative z-10 max-w-6xl mx-auto text-center">
          <h1 className="text-5xl md:text-6xl font-extrabold mb-6 animate-fade-in">
            Welcome to Pet Rescue
          </h1>
          <p className="text-xl md:text-2xl mb-8 max-w-3xl mx-auto">
            Reunite with your lost pets, report found animals, and find your
            perfect companion through adoption.
          </p>
          <Link
            to="/register"
            className="inline-block bg-gradient-to-r from-yellow-500 to-teal-500 text-white font-bold py-4 px-10 rounded-full shadow-lg hover:scale-105 transform transition duration-300"
          >
            Get Started
          </Link>
        </div>
        <div className="absolute bottom-0 left-0 right-0 h-24 bg-gradient-to-t from-blue-50 to-transparent"></div>
      </section>

      <section className="py-16 bg-gradient-to-r from-blue-600 via-teal-600 to-green-500">
        <div className="max-w-6xl mx-auto px-6">
          <h2 className="text-4xl font-bold text-white text-center mb-12">
            Our Impact
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {IMPACT_METRICS.map((metric, index) => (
              <div
                key={index}
                className="bg-white bg-opacity-10 backdrop-blur-lg rounded-2xl p-8 text-center shadow-xl hover:scale-105 transform transition duration-300"
              >
                <span className="material-icons text-6xl text-yellow-400 mb-4">
                  {metric.icon}
                </span>
                <h3 className="text-5xl font-extrabold text-white mb-2">
                  {metric.value}
                </h3>
                <p className="text-lg text-white opacity-90">{metric.label}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="py-20 px-6">
        <div className="max-w-6xl mx-auto">
          <h2 className="text-4xl font-bold text-gray-800 text-center mb-12">
            How It Works
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-2xl transform hover:-translate-y-2 transition duration-300">
              <div className="bg-gradient-to-r from-blue-500 to-teal-500 rounded-full w-16 h-16 flex items-center justify-center mb-6">
                <span className="material-icons text-white text-3xl">pets</span>
              </div>
              <h3 className="text-2xl font-bold text-gray-800 mb-4">
                Report Lost Pets
              </h3>
              <p className="text-gray-600">
                Quickly report your lost pet with detailed information and
                photos to help reunite faster.
              </p>
            </div>

            <div className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-2xl transform hover:-translate-y-2 transition duration-300">
              <div className="bg-gradient-to-r from-teal-500 to-green-500 rounded-full w-16 h-16 flex items-center justify-center mb-6">
                <span className="material-icons text-white text-3xl">
                  search
                </span>
              </div>
              <h3 className="text-2xl font-bold text-gray-800 mb-4">
                Report Found Pets
              </h3>
              <p className="text-gray-600">
                Found a stray? Report it on our platform and help reunite pets
                with their families.
              </p>
            </div>

            <div className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-2xl transform hover:-translate-y-2 transition duration-300">
              <div className="bg-gradient-to-r from-yellow-500 to-orange-500 rounded-full w-16 h-16 flex items-center justify-center mb-6">
                <span className="material-icons text-white text-3xl">
                  volunteer_activism
                </span>
              </div>
              <h3 className="text-2xl font-bold text-gray-800 mb-4">
                Adopt a Pet
              </h3>
              <p className="text-gray-600">
                Browse available pets for adoption and give them a loving
                forever home.
              </p>
            </div>
          </div>
        </div>
      </section>

      <section className="py-20 px-6 bg-gradient-to-br from-blue-100 to-teal-100">
        <div className="max-w-4xl mx-auto">
          <h2 className="text-4xl font-bold text-gray-800 text-center mb-12">
            We would Love to Hear From You
          </h2>

          <div className="bg-white rounded-2xl shadow-xl p-8 mb-12">
            {error && (
              <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg mb-4">
                {error}
              </div>
            )}
            {success && (
              <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded-lg mb-4">
                {success}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div className="mb-6">
                <label className="block text-gray-700 font-semibold mb-2">
                  Name
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-teal-500 focus:outline-none"
                  required
                />
              </div>

              <div className="mb-6">
                <label className="block text-gray-700 font-semibold mb-2">
                  Email
                </label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-teal-500 focus:outline-none"
                  required
                />
              </div>

              <div className="mb-6">
                <label className="block text-gray-700 font-semibold mb-2">
                  Message
                </label>
                <textarea
                  value={formData.message}
                  onChange={(e) =>
                    setFormData({ ...formData, message: e.target.value })
                  }
                  rows="5"
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-teal-500 focus:outline-none resize-none"
                  required
                ></textarea>
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-gradient-to-r from-blue-600 to-teal-600 text-white font-bold py-3 rounded-lg shadow-lg hover:scale-105 transform transition duration-300 disabled:opacity-50"
              >
                {loading ? "Submitting..." : "Submit Feedback"}
              </button>
            </form>
          </div>

          {feedbacks.length > 0 && (
            <div>
              <h3 className="text-2xl font-bold text-gray-800 mb-6">
                Recent Feedback
              </h3>
              <div className="space-y-4">
                {feedbacks.slice(0, 5).map((feedback) => (
                  <div
                    key={feedback.id}
                    className="bg-white rounded-xl shadow-md p-6 hover:shadow-lg transition duration-300"
                  >
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <h4 className="font-bold text-gray-800">
                          {feedback.name}
                        </h4>
                        <p className="text-sm text-gray-500">
                          {feedback.email}
                        </p>
                      </div>
                      <span className="text-xs text-gray-400">
                        {formatDate(feedback.created_at)}
                      </span>
                    </div>
                    <p className="text-gray-700">{feedback.message}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </section>

      <footer className="bg-gradient-to-r from-blue-900 to-teal-900 text-white py-12 px-6">
        <div className="max-w-6xl mx-auto text-center">
          <h3 className="text-2xl font-bold mb-4">Pet Rescue Platform</h3>
          <p className="text-gray-300 mb-6">
            Connecting lost pets with their families and finding homes for those
            in need.
          </p>
          <div className="flex justify-center space-x-6">
            <Link
              to="/about"
              className="hover:text-yellow-400 transition duration-300"
            >
              About Us
            </Link>
            <Link
              to="/contact"
              className="hover:text-yellow-400 transition duration-300"
            >
              Contact
            </Link>
            <Link
              to="/privacy"
              className="hover:text-yellow-400 transition duration-300"
            >
              Privacy Policy
            </Link>
          </div>
          <p className="text-gray-400 text-sm mt-6">
            2024 Pet Rescue. All rights reserved.
          </p>
        </div>
      </footer>
    </div>
  );
}

export default HomePage;
